# Klasifikasi Nilai Akademik Mahasiswa
def konversi_skor_ke_huruf(skor: float) -> str:
    if skor >= 80.0:
        return "A"
    elif skor >= 70.0:
        return "B"
    elif skor >= 60.0:
        return "C"
    elif skor >= 50.0:
        return "D"
    else:
        return "E"

print("Skor 85.5 -> Huruf Mutu:", konversi_skor_ke_huruf(85.5))
print("Skor 72.0 -> Huruf Mutu:", konversi_skor_ke_huruf(72.0))
